import numpy as np
from collections import Counter
lines = open('opt2.xyz').read().split('\n')
n = int(lines[0]); els=[]; P=[]
for l in lines[2:2+n]:
    t=l.split(); els.append(t[0]); P.append([float(x) for x in t[1:4]])
P=np.array(P)
D=np.linalg.norm(P[:,None]-P[None],axis=-1)
rcov={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Cl':1.02,'Ru':1.46}
nb=np.zeros(n,int)
for i in range(n):
    for j in range(i+1,n):
        if D[i,j] < (rcov[els[i]]+rcov[els[j]])*1.25:
            nb[i]+=1; nb[j]+=1
print(Counter(nb.tolist()))
for i in range(n):
    e=els[i]
    exp = {'H':1,'Ru':6,'P':3}.get(e)
    if e=='Cl': exp = 2 if i in (2,3) else 1
    if exp and nb[i]!=exp: print('odd', i, e, nb[i])
